select id, title, scope, type, year, status, summary, link, needs_review, review_note, last_verified from jsonb_populate_recordset(null::policies, $atlas$[{"id":"sustainable-agricultural-development-strategy-2030-egy","title":"Sustainable Agricultural Development Strategy 2030","scope":"EGY","type":"strategy","year":2009,"status":"active (updated)","summary":"Long-run sector strategy covering productivity, water-use efficiency, land expansion and rural livelihoods. AgriTech4Egypt and the 2026 food-security pillars are aligned with it.","link":"https://alliancebioversityciat.org/stories/agritech4egypt-strategic-egypt-italy-partnership-translating-research-market-ready-solutions","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"new-delta-future-of-egypt-land-reclamation-project-egy","title":"New Delta (Future of Egypt) land reclamation project","scope":"EGY","type":"program","year":2026,"status":"inaugurated May 2026; expanding","summary":"About 2.2 million feddans west of the Delta, irrigated with treated drainage water from El Hammam. About LE800bn (~$15bn) invested in land, silos, industrial zones and roads.","link":"https://www.thenationalnews.com/news/mena/2026/05/17/egypts-president-opens-new-delta-project-to-grow-wheat-in-desert-with-artificial-river/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"toshka-agricultural-project-south-valley-egy","title":"Toshka agricultural project (South Valley)","scope":"EGY","type":"program","year":2022,"status":"active","summary":"Revived desert reclamation in Aswan, targeting wheat and dates, with private and state farms, silos and pumped irrigation.","link":"https://egyptian-gazette.com/egypt/toshka-back-on-track/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"five-pillar-food-security-strategy-egy","title":"Five-pillar food security strategy","scope":"EGY","type":"strategy","year":2026,"status":"active","summary":"Expand reclaimed land by 3.5 million feddans, raise yields with technology, close the protein gap, grow exports, and digitize farmer data and AI.","link":"https://english.ahram.org.eg/News/565382.aspx","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"farmer-s-card-kart-el-fallah-e-payment-for-fertilizer-egy","title":"Farmer's Card (Kart El Fallah) e-payment for fertilizer","scope":"EGY","type":"program","year":2026,"status":"national rollout targeted 2026","summary":"Digital smart card that links registered farmers to subsidized fertilizer and other services.","link":"https://english.ahram.org.eg/News/565382.aspx","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agritech4egypt-egypt-italy-egy","title":"AgriTech4Egypt (Egypt-Italy)","scope":"EGY","type":"program","year":2026,"status":"launched 2026; 3-year","summary":"Supports 105 startups (350+ innovators) through challenges, mentoring, validation and pilots with ARC and ASRT.","link":"https://alliancebioversityciat.org/stories/agritech4egypt-strategic-egypt-italy-partnership-translating-research-market-ready-solutions","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"generation-green-2020-2030-mar","title":"Generation Green 2020-2030","scope":"MAR","type":"strategy","year":2020,"status":"active (mid-term review 2026)","summary":"Successor to Plan Maroc Vert: human-capital focus, rural middle class, 1m ha drip; 108bn MAD contracted","link":"https://africa24tv.com/morocco-108-billion-dirhams-invested-since-2020-to-transform-agriculture/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-programme-for-drinking-water-supply-and-irrigation-","title":"National Programme for Drinking Water Supply and Irrigation (PNAEPI) 2020-2027","scope":"MAR","type":"program","year":2020,"status":"active","summary":"Dams, inter-basin transfers, desalination; funding raised to ~150bn MAD","link":"https://medias24.com/2022/11/30/le-fonds-alloue-au-programme-national-dapprovisionnement-en-eau-potable-passe-a-150-mmdh/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"desalination-target-1-7bn-m3-yr-by-2030-mar","title":"Desalination target 1.7bn m3/yr by 2030","scope":"MAR","type":"program","year":2025,"status":"active","summary":"Scale seawater desalination for coastal cities and to free conventional water for agriculture","link":"https://www.moroccoworldnews.com/2025/07/228204/morocco-sets-sights-on-2030-water-security-with-boost-to-desalination-dam-projects/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"localized-irrigation-target-1m-ha-by-2030-mar","title":"Localized irrigation target: 1m ha by 2030","scope":"MAR","type":"program","year":2020,"status":"active","summary":"Drip conversion subsidised via FDA; ~930,000 ha reached by mid-2026","link":"https://hortidaily.com/article/9639707/morocco-wants-to-equip-one-million-hectares-with-localized-irrigation-by-2030","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"plan-maroc-vert-2008-2020-mar","title":"Plan Maroc Vert 2008-2020","scope":"MAR","type":"strategy","year":2008,"status":"completed","summary":"Predecessor strategy; built export agriculture, aggregation model and FDA subsidies","link":"","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"pnia-2-programme-national-d-investissement-agricole-2018-202","title":"PNIA 2 (Programme National d'Investissement Agricole 2018-2025)","scope":"CIV","type":"program","year":2018,"status":"completed 2025","summary":"Second-generation CAADP investment plan (~12,391bn FCFA) focused on modernization, value addition and resilience.","link":"https://connectionivoirienne.net/2026/06/19/economie-le-pm-mambe-lance-le-processus-dinvestissement-agricole-de-3eme-generation-pnia-3/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"pnia-3-third-generation-agricultural-investment-programme-ci","title":"PNIA 3 (third-generation agricultural investment programme)","scope":"CIV","type":"program","year":2026,"status":"in formulation (launched Jun 2026)","summary":"Aligned to the PND 2026-2030. Five axes: food sovereignty, competitiveness, financing, rural land security, climate resilience and sustainability.","link":"https://connectionivoirienne.net/2026/06/19/economie-le-pm-mambe-lance-le-processus-dinvestissement-agricole-de-3eme-generation-pnia-3/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"rural-land-law-loi-n98-750-and-presfor-land-security-program","title":"Rural Land Law (Loi n°98-750) and PRESFOR land-security programme","scope":"CIV","type":"law","year":1998,"status":"in force; certification ongoing","summary":"Legal basis for customary-to-certified rural land rights. AFOR and the World Bank-backed PRESFOR are accelerating certificates.","link":"https://www.fratmat.info/article/2645025/economie/securisation-fonciere-2-millions-dhectares-certifies","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"cocoa-coffee-marketing-reform-forward-sales-minimum-60-of-ci","title":"Cocoa/coffee marketing reform (forward sales, minimum 60% of CIF price)","scope":"CIV","type":"law","year":2012,"status":"active","summary":"CCC-administered marketing system that guarantees a farm-gate price of at least 60% of the international price.","link":"https://www.fratmat.info/article/2644229/economie/10e-edition-des-journees-nationales-du-cacao-et-du-chocolat-la-jeunesse-appelee-a-prendre-le-relais-pour-assurer-lavenir-de-la-filiere","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-agronomic-research-strategic-plan-2026-2035-civ","title":"National Agronomic Research Strategic Plan 2026-2035","scope":"CIV","type":"strategy","year":2026,"status":"validation 2026","summary":"CNRA's 10-year plan covering climate adaptation, productivity, food safety, genetic resources and faster delivery of innovations to farmers.","link":"https://www.incotedivoire.net/economic/new/Agricultural%20Sector%20Development:%20Minister%20Bernard%20Kini%20Como%C3%A9%20Launches%20Strategic%20Planning%20for%20Agronomic%20Research%20%282026%E2%80%932035%29","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agropoles-agro-industrial-poles-programme-civ","title":"Agropoles (agro-industrial poles) programme","scope":"CIV","type":"program","year":2019,"status":"under implementation","summary":"Regional agro-industrial clusters (e.g., Agropole Sud, Nord) for processing and market access.","link":"https://fr.allafrica.com/stories/202403200030.html","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"feed-ghana-programme-gha","title":"Feed Ghana Programme","scope":"GHA","type":"program","year":2025,"status":"active","summary":"Flagship agriculture programme: irrigation rehabilitation, small dams, solar boreholes, Farmer Service Centres, seed systems (e.g., rice-seed independence by 2027), urban farmers' markets and agro-industrial linkages.","link":"https://www.myjoyonline.com/agric-minister-outlines-key-developments-under-feed-ghana-programme-in-past-nine-months/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"planting-for-food-and-jobs-pfj-1-0-and-2-0-gha","title":"Planting for Food and Jobs (PFJ 1.0 and 2.0)","scope":"GHA","type":"program","year":2017,"status":"superseded (2025)","summary":"Input subsidy and credit programme (PFJ 2.0 from 2023 shifted to input credit). Replaced by Feed Ghana after the 2025 change of government.","link":"https://www.graphic.com.gh/news/general-news/ghana-news-attaining-food-sufficiency-govt-to-introduce-2-agric-programmes-minister-designate.html","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"nkoko-nkitinkiti-poultry-programme-gha","title":"Nkoko Nkitinkiti (poultry) Programme","scope":"GHA","type":"program","year":2025,"status":"active","summary":"Poultry value-chain programme under Feed Ghana to cut chicken imports. GH¢36.75m in the H1 2026 allotment.","link":"https://www.myjoyonline.com/finance-agriculture-ministries-clash-over-gh%c2%a21-6bn-funding-claims/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"cocoa-sector-reforms-local-processing-drive-gha","title":"Cocoa sector reforms / local processing drive","scope":"GHA","type":"strategy","year":2026,"status":"announced Feb 2026","summary":"COCOBOD and MoF policy shift toward local bean processing, local bond financing and arrears clearance.","link":"https://allafrica.com/stories/202602120458.html","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"2026-budget-agriculture-allocations-gha","title":"2026 Budget agriculture allocations","scope":"GHA","type":"program","year":2026,"status":"under implementation; release disputes","summary":"Funds Farmer Service Centres, fertilizer and seed, irrigation, NAFCO and oil-palm development. MoFA and MoF disagree publicly over releases.","link":"https://www.myjoyonline.com/finance-agriculture-ministries-clash-over-gh%c2%a21-6bn-funding-claims/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-agricultural-technology-and-innovation-policy-natip","title":"National Agricultural Technology and Innovation Policy (NATIP) 2022-2027","scope":"NGA","type":"strategy","year":2022,"status":"active","summary":"Sector policy on productivity, mechanisation, digital agriculture, value chains and climate; anchors NAGS-AP","link":"https://agriculture.gov.ng/wp-content/uploads/2024/06/National-Agricultural-Technology-and-Innovation-Policy-NATIP-2022-2027.pdf","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-agricultural-growth-scheme-agro-pocket-nags-ap-phas","title":"National Agricultural Growth Scheme - Agro-Pocket (NAGS-AP), Phase II","scope":"NGA","type":"program","year":2026,"status":"active","summary":"AfDB $200m sector budget support (from Mar 2026, 4 yrs) for inputs and tech; targets 5x wheat, +20% rice","link":"https://nairametrics.com/2026/02/14/african-development-bank-funds-200-million-nigerias-climate-smart-farming","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"special-agro-industrial-processing-zones-sapz-phase-2-nga","title":"Special Agro-Industrial Processing Zones (SAPZ) Phase 2","scope":"NGA","type":"program","year":2025,"status":"active","summary":"AfDB and partners mobilise $2.2bn to extend agro-industrial zones to 24 states (phase 1: 7 states + FCT)","link":"https://www.thecable.ng/afdb-secures-2-2bn-for-phase-two-of-sapz-in-nigeria","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"renewed-hope-cooperative-reform-and-revamp-programme-rh-crrp","title":"Renewed Hope Cooperative Reform and Revamp Programme (RH-CRRP 2030)","scope":"NGA","type":"program","year":2026,"status":"active","summary":"Seven-pillar cooperative reform framework approved in March 2026","link":"https://fmino.gov.ng/statement-by-the-honourable-minister-of-state-for-agriculture-and-food-security-sen-dr-aliyu-sabi-abdullahi-con-on-the-occasion-of-world-food-day-2026/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-farmers-registry-nin-linked-and-e-extension-nga","title":"National Farmers Registry (NIN-linked) and e-extension","scope":"NGA","type":"program","year":2024,"status":"active","summary":"Digital farmer registry linked to National Identity Number for targeting inputs and digital extension","link":"https://fmino.gov.ng/statement-by-the-honourable-minister-of-state-for-agriculture-and-food-security-sen-dr-aliyu-sabi-abdullahi-con-on-the-occasion-of-world-food-day-2026/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"land-use-act-nga","title":"Land Use Act","scope":"NGA","type":"law","year":1978,"status":"in force","summary":"Vests land in state governors; certificate-of-occupancy system widely seen as limiting farmland titling and collateral","link":"","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"rural-land-administration-and-use-proclamation-no-1324-2024-","title":"Rural Land Administration and Use Proclamation No. 1324/2024","scope":"ETH","type":"law","year":2024,"status":"in force","summary":"Federal rural land law: registration, leasing and collateralisation of use-rights; central land database","link":"https://leap.unep.org/en/countries/et/national-legislation/rural-land-administration-and-use-proclamation-no-13242024","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"digital-agriculture-roadmap-2025-2032-eth","title":"Digital Agriculture Roadmap 2025-2032","scope":"ETH","type":"strategy","year":2025,"status":"active","summary":"ATI/MoA roadmap: 6 solutions across 22 priority areas; phase 1 (2025-29) foundations, phase 2 scale-up","link":"https://capitalethiopia.com/2025/02/10/ethiopia-bets-big-on-digital-agriculture-to-boost-food-security-with-2025-2032-roadmap","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agricultural-commercialization-clusters-cluster-farming-eth","title":"Agricultural Commercialization Clusters / cluster farming","scope":"ETH","type":"program","year":2019,"status":"active","summary":"ATI-led clustering of smallholders; ~12.3m ha by 2024/25","link":"https://www.ena.et/web/eng/w/eng_8580001","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"lowland-irrigated-wheat-import-substitution-initiative-eth","title":"Lowland irrigated wheat import-substitution initiative","scope":"ETH","type":"program","year":2019,"status":"active","summary":"Large-scale dry-season irrigated wheat in lowlands to cut wheat imports","link":"https://www.ena.et/web/eng/w/eng_8007134","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"ten-years-development-plan-2021-2030-eth","title":"Ten Years Development Plan 2021-2030","scope":"ETH","type":"strategy","year":2021,"status":"active","summary":"National development plan with agriculture as a lead growth sector","link":"","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"contract-farming-proclamation-eth","title":"Contract Farming Proclamation","scope":"ETH","type":"law","year":2022,"status":"approved by Council of Ministers; referred to parliament","summary":"Legal framework for contract farming to raise productivity and market linkages","link":"https://www.capitalethiopia.com/2022/08/19/contract-farming-bill-passed/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agricultural-sector-transformation-and-growth-strategy-astgs","title":"Agricultural Sector Transformation and Growth Strategy (ASTGS) 2019-2029","scope":"KEN","type":"strategy","year":2019,"status":"active","summary":"Ten-year sector plan with nine flagships: farmer incomes, value addition, food resilience, digital and data","link":"https://fsd.kilimo.go.ke/pdfs/agricultural-sector-transformation-and-growth-strategy.pdf","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-irrigation-sector-investment-plan-nisip-ken","title":"National Irrigation Sector Investment Plan (NISIP)","scope":"KEN","type":"program","year":2024,"status":"active","summary":"Roadmap to grow irrigated area from 664k acres (2021/22) to 1.29m acres by 2027/28 and expand water storage","link":"https://citizen.digital/article/kenya-targets-doubling-irrigated-land-to-boost-food-security-by-2028-n383910","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-fertilizer-subsidy-programme-via-kiamis-e-voucher-k","title":"National Fertilizer Subsidy Programme via KIAMIS e-voucher","scope":"KEN","type":"program","year":2023,"status":"active","summary":"Subsidised fertiliser (Ksh2,500 per bag) for KIAMIS-registered farmers; 12.5m bags released for the 2026 long rains","link":"https://www.the-star.co.ke/counties/central/2026-01-15-government-rolls-out-125-million-subsidised-fertiliser-bags-ahead-of-long-rains","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-agroecology-strategy-for-food-system-transformation","title":"National Agroecology Strategy for Food System Transformation 2024-2033","scope":"KEN","type":"strategy","year":2024,"status":"active","summary":"Framework to scale agroecological practices, soil health and climate resilience","link":"https://kilimo.go.ke/wp-content/uploads/2025/09/National-Agroecology-Strategy-for-Food-System-Transformation-2024-2033.pdf","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"moald-strategic-plan-2023-2027-ken","title":"MoALD Strategic Plan 2023-2027","scope":"KEN","type":"strategy","year":2023,"status":"active","summary":"Ministry delivery plan aligned with the Bottom-Up Economic Transformation Agenda (BETA) value chains","link":"https://kilimo.go.ke/wp-content/uploads/2024/08/Ministrys-Strategic-Plan-for-2023-2027-Final-Version-for-validation-and-Stakeholder-Engagement-19.12.2023-1.doc","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-rice-development-strategy-2019-2030-ken","title":"National Rice Development Strategy 2019-2030","scope":"KEN","type":"strategy","year":2019,"status":"active","summary":"Targets rice self-sufficiency through irrigation schemes and mechanisation","link":"https://kilimo.go.ke/wp-content/uploads/2025/09/National-Rice-Development-Strategy-2019-2030.pdf","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"fifth-strategic-plan-for-agriculture-transformation-psta5-20","title":"Fifth Strategic Plan for Agriculture Transformation (PSTA5) 2024-2029","scope":"RWA","type":"strategy","year":2024,"status":"active","summary":"RWF 6.6trn (~US$5.1bn) food-systems and climate-resilience plan; ~44% private financing","link":"https://www.minagri.gov.rw/updates/news-details/rwanda-launches-5th-strategic-plan-for-agriculture-transformation","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-strategy-for-transformation-nst2-2024-2029-rwa","title":"National Strategy for Transformation (NST2) 2024-2029","scope":"RWA","type":"strategy","year":2024,"status":"active","summary":"National plan: +50% priority crop output, >6% ag growth, double ag exports to US$1.9bn","link":"https://www.minagri.gov.rw/updates/news-details/rwanda-agricultural-show-2026-stakeholders-urged-to-leverage-innovation-and-strategic-partnerships-for-agri-food-systems-transformation","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"irrigation-expansion-target-to-2029-rwa","title":"Irrigation expansion target to 2029","scope":"RWA","type":"program","year":2026,"status":"active","summary":"Expand irrigated area 85% to 132,961 ha by 2029; marshland irrigation to 42,473 ha","link":"https://allafrica.com/stories/202602030013.html","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"concessional-agricultural-lending-scheme-rwa","title":"Concessional agricultural lending scheme","scope":"RWA","type":"program","year":2023,"status":"active","summary":"Halves interest on farm loans; RWF 55bn approved, 30.9bn disbursed via 31 FIs","link":"https://www.minagri.gov.rw/updates/news-details/rwanda-agricultural-show-2026-stakeholders-urged-to-leverage-innovation-and-strategic-partnerships-for-agri-food-systems-transformation","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"fy2026-27-budget-minagri-allocation-41-3-rwa","title":"FY2026/27 budget: MINAGRI allocation +41.3%","scope":"RWA","type":"program","year":2026,"status":"active","summary":"Largest ministry increase, mainly for fertiliser subsidies, post-harvest storage, strategic grain reserves","link":"https://www.ktpress.rw/2026/07/rwandas-2026-27-budget-agriculture-biggest-winner-disaster-management-funding-down-70/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agenda-10-30-tza","title":"Agenda 10/30","scope":"TZA","type":"strategy","year":2022,"status":"active","summary":"Targets more than 10% agricultural growth by 2030, $5bn+ agri exports, 8.5 million ha irrigated, post-harvest losses cut from 35% to 5%, and agro-processing from 10% to 50%.","link":"https://dailynews.co.tz/what-agriculture-reforms-promise-2030/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"building-a-better-tomorrow-bbt-youth-and-women-initiative-tz","title":"Building a Better Tomorrow (BBT) Youth and Women Initiative","scope":"TZA","type":"program","year":2022,"status":"expanding nationwide (2026/27)","summary":"Youth block farms with irrigation, land allocation, training and start-up support. Anchors the TZS 1.1tn 2026/27 budget.","link":"https://thecitizen.co.tz/tanzania/news/national/bbt-programme-anchors-sh1trn-agriculture-budget-5440148","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"smallholder-irrigation-borehole-programme-nirc-tza","title":"Smallholder Irrigation Borehole Programme (NIRC)","scope":"TZA","type":"program","year":2023,"status":"under implementation","summary":"67,000 subsidized boreholes and pumps, plus 1,000 solar pumps, 146 construction projects and 634 scheme designs.","link":"https://www.tanzaniainvest.com/agriculture/irrigation-borehole-drilling-program","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agricultural-sector-development-programme-ii-asdp-ii-tza","title":"Agricultural Sector Development Programme II (ASDP II)","scope":"TZA","type":"program","year":2017,"status":"active (to 2027/28)","summary":"Sector-wide framework covering land and water, productivity, commercialization and coordination. CAADP-aligned.","link":"https://www.kilimo.go.tz","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"tanzania-development-vision-2050-tza","title":"Tanzania Development Vision 2050","scope":"TZA","type":"strategy","year":2025,"status":"active","summary":"Long-term national vision with agriculture and agro-industrialization as core pillars.","link":"https://dailynews.co.tz/?p=106131","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"ministry-of-agriculture-2026-27-budget-tza","title":"Ministry of Agriculture 2026/27 budget","scope":"TZA","type":"program","year":2026,"status":"approved Apr/May 2026","summary":"About TZS 1.1tn, with a target of 2.1 million tonnes of cash crops (+32%), 235,000 t of avocado and NAESA operational from July 2026.","link":"https://www.tanzaniainvest.com/agriculture/agriculture-budget-2026-2027-cash-crop-target","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agriculture-and-agro-processing-master-plan-aamp-zaf","title":"Agriculture and Agro-processing Master Plan (AAMP)","scope":"ZAF","type":"strategy","year":2022,"status":"active; minister seeks faster rollout (2026)","summary":"Social compact of government, business, labour and civil society to grow output, exports, jobs and inclusion across value chains.","link":"https://www.foodformzansi.co.za/three-years-on-is-the-master-plan-delivering-for-farmers/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"blended-finance-scheme-department-of-agriculture-and-land-ba","title":"Blended Finance Scheme (Department of Agriculture and Land Bank)","scope":"ZAF","type":"program","year":2023,"status":"active","summary":"R3.2bn blended-finance window that combines grants and Land Bank loans for black and emerging producers.","link":"https://www.gov.za/node/816933","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"fmd-control-and-vaccination-strategy-zaf","title":"FMD control and vaccination strategy","scope":"ZAF","type":"program","year":2026,"status":"active / emergency","summary":"Mass FMD vaccination (13.5m+ doses imported), state vaccination where farmers lack means, and biosecurity compliance for trade.","link":"https://www.foodformzansi.co.za/aucamp-outlines-strategy-for-biosecurity-trade-and-infrastructure/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"expropriation-act-zaf","title":"Expropriation Act","scope":"ZAF","type":"law","year":2025,"status":"in force; litigated","summary":"Replaces the 1975 Act and sets out expropriation procedures, including nil compensation in limited cases. Contested in courts and within the GNU.","link":"https://www.gov.za","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"national-logistics-crisis-committee-freight-logistics-roadma","title":"National Logistics Crisis Committee / Freight Logistics Roadmap","scope":"ZAF","type":"strategy","year":2023,"status":"active","summary":"Reforms opening rail and ports to private operators, addressing export logistics constraints that matter for agriculture.","link":"https://www.transnet.net","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"maputo-declaration-caadp-launch-au","title":"Maputo Declaration / CAADP launch","scope":"AU","type":"AU declaration","year":2003,"status":"Superseded by Malabo (2014) and Kampala (2026-35); the 10% budget target remains a reference point","summary":"Created CAADP; pledged at least 10% of national budgets to agriculture and 6% annual agricultural growth. Most countries never consistently hit the 10% target.","link":"https://www.downtoearth.org.in/africa/african-leaders-adopt-new-kampala-declaration-and-10-year-strategy-to-transform-agriculture","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"malabo-declaration-on-accelerated-agricultural-growth-and-tr","title":"Malabo Declaration on Accelerated Agricultural Growth and Transformation","scope":"AU","type":"AU declaration (CAADP 2015-2025)","year":2014,"status":"Expired 2025. In the 4th Biennial Review (2023), no country was on track (benchmark 9.29); the hunger-by-2025 goal was missed by all member states","summary":"Seven commitments: recommit to CAADP, 10% spending, end hunger by 2025, halve poverty, triple intra-African agri trade, enhance resilience, mutual accountability through biennial reviews.","link":"https://esaff.org/index-php/wp-content/uploads/2024/07/Policy-Brief-SADC-Performance-in-the-CAADP-BR-Report-wb.pdf","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"kampala-caadp-declaration-on-building-resilient-and-sustaina","title":"Kampala CAADP Declaration on Building Resilient and Sustainable Agrifood Systems (CAADP Strategy & Action Plan 2026-2035)","scope":"AU","type":"AU declaration + 10-year strategy","year":2025,"status":"Adopted 11 Jan 2025 at the Extraordinary AU Summit in Kampala; implementation began 2026 (national agrifood systems investment plans being domesticated)","summary":"By 2035: mobilize US$100bn public and private investment, raise agrifood output 45%, halve post-harvest loss, triple intra-African trade in agrifood products and inputs, raise local processing to 35% of agrifood GDP, eradicate PPR by 2030, empower women and youth, strengthen governance.","link":"https://www.ilri.org/news/au-endorses-10-year-plan-build-resilient-agrifood-systems-africa","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agreement-establishing-the-african-continental-free-trade-ar","title":"Agreement Establishing the African Continental Free Trade Area (AfCFTA)","scope":"AU","type":"Continental trade treaty","year":2018,"status":"In force 30 May 2019; trading from 1 Jan 2021. 50 of 54 signatories ratified (Sept 2026). 26 states had gazetted tariff schedules by June 2026. 100% of rules of origin agreed Feb 2026. Guided Trade Initiative (2022) concluded 2025. Phase II protocols (investment, IP, competition, digital trade, women and youth) await ratification","summary":"Single market for goods and services across 54 states. Liberalizes 90% of tariff lines, plus protocols on services, investment, digital trade, and a planned industrial policy protocol.","link":"https://www.tralac.org/documents/resources/faqs/7994-afcfta-frequently-asked-questions-updated-september-2026.html","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"programme-for-infrastructure-development-in-africa-pida-pap-","title":"Programme for Infrastructure Development in Africa (PIDA) - PAP I and PAP II","scope":"AU","type":"Continental infrastructure program","year":2012,"status":"PAP I (2012-2020): ~409 projects; commitments of US$82bn vs US$67.9bn projected. PAP II (2021-2030): 69 projects, ~US$160.7bn, corridor approach, adopted 2021","summary":"Cross-border transport, energy, transboundary water and ICT backbone, with ~US$360bn total infrastructure need projected to 2040. Key for agri corridors and power pools.","link":"https://www.au-pida.org/pida-priority-action-plans-pap/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"nairobi-declaration-and-africa-fertilizer-soil-health-afsh-a","title":"Nairobi Declaration and Africa Fertilizer & Soil Health (AFSH) Action Plan 2024-2034","scope":"AU","type":"AU summit declaration + 10-year action plan","year":2024,"status":"Adopted at the AFSH Summit in Nairobi, 7-9 May 2024; implementation and country roadmaps under way; financing via AfDB-hosted Africa Fertilizer Financing Mechanism","summary":"Triple fertilizer use from 18 to 54 kg/ha by 2034; double cereal yields from 1.7 to 3.5 t/ha; put 30% of land under sustainable soil management (from 8.2%); keep nitrogen use efficiency at 60% or above; give 70% of farmers access to advisory services; double agricultural growth to 8%. Endorsed the Soil Initiative for Africa.","link":"https://au.int/sites/default/files/documents/43208-doc-EN_Africa_Fertilizer_and_Soil_Health_Action_Plan.pdf","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"digital-transformation-strategy-for-africa-2020-2030-au","title":"Digital Transformation Strategy for Africa 2020-2030","scope":"AU","type":"AU strategy","year":2020,"status":"Active; mid-term implementation; continental data governance frameworks under validation (Dec 2025) toward a Digital Single Market by 2030","summary":"Aims at a Digital Single Market by 2030. Pillars include digital infrastructure, skills, digital agriculture, and e-government. Basis for the AU Data Policy Framework.","link":"https://meatechwatch.com/2025/12/04/au-begins-validation-of-continental-data-governance-frameworks-to-drive-africas-digital-single-market-by-2030/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"au-data-policy-framework-au","title":"AU Data Policy Framework","scope":"AU","type":"AU policy framework","year":2022,"status":"Released 28 July 2022; being domesticated; calls for ratification of the Malabo Convention on cyber security and data protection","summary":"Principles for data governance, cross-border data flows, data protection, and value enablers. Builds on the DTS and enables farmer-data sharing and DPI interoperability.","link":"https://fpf.org/blog/the-african-unions-data-policy-framework-context-key-takeaways-and-implications-for-data-protection-on-the-continent/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agenda-2063-the-africa-we-want-au","title":"Agenda 2063: The Africa We Want","scope":"AU","type":"AU long-term development blueprint","year":2015,"status":"Active; Second Ten-Year Implementation Plan (2024-2033) under way. Flagships include AfCFTA, PIDA, and the Single African Air Transport Market","summary":"50-year vision. Agriculture modernization, industrialization and integrated infrastructure are core goals; CAADP is the agriculture vehicle.","link":"https://au.int/en/agenda2063/overview (could not be opened: fetch blocked; standard AU URL)","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"dakar-2-summit-feed-africa-food-sovereignty-and-resilience-a","title":"Dakar 2 Summit: Feed Africa - Food Sovereignty and Resilience","scope":"AU","type":"AfDB-led heads of state summit + Country Food & Agriculture Delivery Compacts","year":2023,"status":"Held Jan 2023; US$72bn mobilized. By May 2024, 6 countries had presidential delivery councils and 12 more were setting them up","summary":"Country compacts to scale proven technologies (TAAT): heat-tolerant wheat, maize, rice, soybean, and livestock. Linked to Special Agro-Industrial Processing Zones.","link":"https://allafrica.com/stories/202405290008.html","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"mission-300-world-bank-group-african-development-bank-au","title":"Mission 300 (World Bank Group & African Development Bank)","scope":"AU","type":"MDB energy access initiative + national energy compacts","year":2024,"status":"Launched 2024; Dar es Salaam Energy Summit Jan 2025 national compacts. 64m people connected by Oct 2026 (WBG 59m, AfDB 5m+)","summary":"Connect 300 million Africans to electricity by 2030 through grid and distributed renewables, utility reform and private capital. Critical for irrigation, cold chain and processing.","link":"https://gna.org.gh/2026/10/world-bank-afdb-connect-64-million-africans-to-electricity/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"accelerated-industrial-development-for-africa-aida-plan-of-a","title":"Accelerated Industrial Development for Africa (AIDA) Plan of Action","scope":"AU","type":"AU industrial policy framework","year":2008,"status":"Active framework; reinforced by the Niamey Extraordinary Summit on Industrialization (25 Nov 2022)","summary":"Seven clusters: industrial policy, production and trade capacity, infrastructure and energy, skills, innovation and R&D, finance, sustainability. Niamey 2022 committed 5-10% of budgets to industry, 10% of public procurement for local firms, SEZs as regional value chain hubs, food and cotton value chains, and an African Industrial Development Index.","link":"https://au.int/en/ti/aida/about","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"niamey-declaration-on-industrialization-and-economic-diversi","title":"Niamey Declaration on Industrialization and Economic Diversification","scope":"AU","type":"AU extraordinary summit decisions","year":2022,"status":"Adopted Nov 2022; AU Commission developing regional value chain recommendations; AfCFTA mandated to negotiate an Industrial Policy protocol","summary":"Commodity-based industrialization via regional value chains (agro-food, cotton apparel, pharma, minerals, automotive), SEZs/industrial parks, local procurement and skills.","link":"https://au.int/sites/default/files/pressreleases/42435-pr-PRESS_RELEASE_ASSEMBLY_DECISIONS_ON_INDUSTRIALIZATION.pdf","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"regional-seed-harmonization-ecowas-2008-regulation-sadc-harm","title":"Regional seed harmonization (ECOWAS 2008 regulation; SADC Harmonized Seed Regulatory System 2008/2013; COMESA COMSHIP 2014)","scope":"AU","type":"REC regulations","year":2014,"status":"Partially implemented. COMESA: 7 of 21 states had domesticated rules by 2018. Regional variety catalogues are operational (COMESA, SADC) and companies list varieties via Seeds2B. ECOWAS/UEMOA/CILSS share a regional catalogue","summary":"Mutual recognition of variety release, certification and phytosanitary rules: a variety released in 2 member states can be marketed region-wide, cutting time and cost to market.","link":"https://www.comesa.int/seven-comesa-states-have-harmonized-seed-regulations/","needs_review":false,"review_note":null,"last_verified":"2026-11-03"}]$atlas$::jsonb)
