insert into gaps (id, title, scope, segment, root_causes, evidence, evidence_source, who_is_working, opportunity, needs_review, review_note, last_verified)
select id, title, scope, segment, root_causes, evidence, evidence_source, who_is_working, opportunity, needs_review, review_note, last_verified from jsonb_populate_recordset(null::gaps, $atlas$[{"id":"water-scarcity-and-nile-dependence-egy","title":"Water scarcity and Nile dependence","scope":"EGY","segment":"irrigation & water","root_causes":"Fixed Nile allocation, upstream GERD uncertainty and population growth. Old-lands irrigation still relies on flood methods, and megaprojects depend on energy-intensive pumping of treated drainage water.","evidence":"The New Delta needs a 170 km canal with 13 pumping stations to move treated drainage water west (The National, May 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"persistent-wheat-and-red-meat-import-gaps-egy","title":"Persistent wheat and red-meat import gaps","scope":"EGY","segment":"inputs & seeds","root_causes":"Limited arable land, low feed self-sufficiency and smallholder fragmentation.","evidence":"MoALR targets only 50% wheat self-sufficiency. Local maize covers about 55% of need, and the red-meat target is 60% (Egypt Today, April 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"state-and-military-led-delivery-crowds-out-private-and-small","title":"State- and military-led delivery crowds out private and smallholder models","scope":"EGY","segment":"finance & insurance","root_causes":"Megaprojects are run by the Future of Egypt Authority and armed-forces bodies. Data is opaque, and blended or private finance for smallholders is limited.","evidence":"The New Delta is operated by Future of Egypt, with AFEA and NSPO as main implementers (The National, May 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"weak-extension-and-smallholder-tech-adoption-in-the-old-land","title":"Weak extension and smallholder tech adoption in the old lands","scope":"EGY","segment":"climate & extension","root_causes":"Fragmented holdings, an ageing public extension workforce and a small agri-tech VC pool.","evidence":"Donor-led AgriTech4Egypt (2026) aims to support only 105 startups over three years. Most agritech funding rounds are undisclosed or seed-stage.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"energy-cost-of-pumping-and-desalination-linked-expansion-egy","title":"Energy cost of pumping and desalination-linked expansion","scope":"EGY","segment":"energy","root_causes":"Desert agriculture depends on lifting water, and power shortages hit Egypt in 2024-25.","evidence":"Pumping-based conveyance at the New Delta and Toshka. Wilo and Hassan Allam hold pump and irrigation contracts in Toshka.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"structural-water-scarcity-and-drought-mar","title":"Structural water scarcity and drought","scope":"MAR","segment":"irrigation & water","root_causes":"Climate change, groundwater over-extraction, export-crop water intensity","evidence":"Agricultural dams at 26% fill in Jan 2025; 1.7bn m3/yr desalination target by 2030 (MWN, Jul 2025)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"dualistic-sector-rain-fed-smallholders-lag-mar","title":"Dualistic sector: rain-fed smallholders lag","scope":"MAR","segment":"climate & extension","root_causes":"Investment skewed to irrigated export farms; small farm size; low insurance uptake","evidence":"Generation Green mid-term review commissioned (BCG, 11.8m MAD) to recalibrate (Africa24, Jul 2026)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"land-tenure-complexity-mar","title":"Land tenure complexity","scope":"MAR","segment":"finance & insurance","root_causes":"Collective (soulaliyate), habous and undivided family lands limit titling and credit","evidence":"Ongoing melkisation of collective lands under Generation Green","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"livestock-herd-and-feed-shock-mar","title":"Livestock herd and feed shock","scope":"MAR","segment":"inputs & seeds","root_causes":"Drought-reduced pasture and feed costs; import dependence for feed grains","evidence":"Renaming of ministry to include 'Food Sovereignty' in Oct 2026 signals domestic supply priority","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"energy-cost-of-desalinated-irrigation-water-mar","title":"Energy cost of desalinated irrigation water","scope":"MAR","segment":"energy","root_causes":"Desalination is energy-intensive; renewables integration still scaling","evidence":"Government linking renewables to agriculture to secure food and water (Hespress)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"rural-land-tenure-insecurity-civ","title":"Rural land tenure insecurity","scope":"CIV","segment":"finance & insurance","root_causes":"Customary tenure, slow and costly certification under the 1998 Rural Land Law, and conflicts between migrants and autochthonous communities.","evidence":"AFOR: about 1.75 million ha certified at 30 Sept 2026 (~2 million ha by Oct) and 67% of villages delimited (Fraternité Matin, 7 Oct 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"food-crop-productivity-rice-imports-and-low-irrigation-civ","title":"Food-crop productivity, rice imports and low irrigation","scope":"CIV","segment":"irrigation & water","root_causes":"Investment has historically favoured export crops. Irrigation schemes and mechanization for lowland rice are limited.","evidence":"PNIA 3 lists food sovereignty as axis 1. Food crops grew 9% in 2025 but remain largely rain-fed.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"thin-agricultural-credit-and-finance-civ","title":"Thin agricultural credit and finance","scope":"CIV","segment":"finance & insurance","root_causes":"Banks see high risk, untitled land cannot serve as collateral, and agricultural insurance is weak.","evidence":"PNIA 3 adds a dedicated axis on 'mécanismes de financement renforcés'. The PM calls for 'une agriculture d'entreprise, mieux financée' (June 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"ageing-cocoa-orchards-disease-and-deforestation-compliance-c","title":"Ageing cocoa orchards, disease and deforestation compliance","scope":"CIV","segment":"climate & extension","root_causes":"Swollen-shoot virus, ageing trees and farmers, and EUDR traceability requirements.","evidence":"FIRCA has published a cocoa and coffee orchard-regeneration guide. The CCC focuses on youth succession (JNCC, Sept 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"incomplete-agro-industrial-zones-agropoles-civ","title":"Incomplete agro-industrial zones (agropoles)","scope":"CIV","segment":"industrial zones","root_causes":"Slow PPP structuring and delays in feeder infrastructure.","evidence":"The agropoles programme has been in rollout since 2019 and is still being implemented.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"very-low-irrigated-area-and-poor-o-m-of-existing-schemes-gha","title":"Very low irrigated area and poor O&M of existing schemes","scope":"GHA","segment":"irrigation & water","root_causes":"Chronic under-funding, incomplete dams, vandalism and weak scheme management. A long-planned shift to private O&M was never fully realized.","evidence":"Only about 210,000 ha developed vs 1.9 million ha potential (Graphic, 2018). MiDA in March 2026 found the Subinja scheme stripped of pumps and transformer, and a rice scheme using 300 of 1,000 acres.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"budget-releases-and-policy-discontinuity-gha","title":"Budget releases and policy discontinuity","scope":"GHA","segment":"finance & insurance","root_causes":"IMF-era fiscal consolidation, cash-based allotments, and each new government replacing its predecessor's flagship programme.","evidence":"MoFA vs MoF dispute (June 2026): H1 allotment capped at GH¢910m, Feed Ghana line GH¢4.5m, against MoF's claim of GH¢1.6bn released.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"cocoa-sector-debt-and-low-local-processing-gha","title":"Cocoa sector debt and low local processing","scope":"GHA","segment":"processing","root_causes":"COCOBOD's syndicated-loan model broke down, leaving legacy debt, pricing mismatches and dependence on raw-bean exports.","evidence":"COCOBOD CEO cites GH¢26bn in road contracts and other legacy debts. Stranded beans in 2026. Pivot to processors announced Feb 2026.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"low-mechanization-and-seed-self-sufficiency-gha","title":"Low mechanization and seed self-sufficiency","scope":"GHA","segment":"mechanization","root_causes":"Fragmented smallholdings, little tractor-hire finance and dependence on imported seed.","evidence":"The rice-seed independence target (10,000 t by 2027) is still under development via the Korea Rural Cooperation project.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"post-harvest-losses-and-weak-storage-and-market-links-gha","title":"Post-harvest losses and weak storage and market links","scope":"GHA","segment":"storage & cold chain","root_causes":"Limited warehousing and buffer-stock financing, and poor feeder roads.","evidence":"NAFCO buffer stock allocated only GH¢30m in the H1 2026 allotment.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"insecurity-displacing-farmers-in-core-food-belts-nga","title":"Insecurity displacing farmers in core food belts","scope":"NGA","segment":"logistics & market access","root_causes":"Banditry, kidnapping and farmer-herder conflict; weak rural policing; land-use competition","evidence":"842 deaths and 279 abductions in 156 incidents in May 2026 (Nextier, via AllAfrica Jul 2026)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"low-and-poorly-executed-public-agriculture-spending-nga","title":"Low and poorly executed public agriculture spending","scope":"NGA","segment":"finance & insurance","root_causes":"Oil-revenue volatility; recurrent-heavy spending; poor release discipline; limited transparency","evidence":"2026 allocation N1.45trn (~2.4-2.8%) vs 10% target; in 2019 only N44.96bn released of N137.9bn approved","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"minimal-irrigation-nga","title":"Minimal irrigation","scope":"NGA","segment":"irrigation & water","root_causes":"Under-maintained river-basin authority dams; energy cost of pumping; rain-fed reliance","evidence":"About 154,000 ha irrigated (AllAfrica Jul 2026); NISER flags irrigation scale-up as under-funded","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agro-processing-zones-slow-to-deliver-nga","title":"Agro-processing zones slow to deliver","scope":"NGA","segment":"industrial zones","root_causes":"Complex multi-tier (federal, state, private) governance; counterpart funding delays; off-site power and roads not ready","evidence":"AfDB rated SAPZ unsatisfactory with 12% disbursement (AllAfrica Jul 2026)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"storage-cold-chain-and-power-deficit-nga","title":"Storage, cold chain and power deficit","scope":"NGA","segment":"storage & cold chain","root_causes":"Unreliable grid supply, diesel dependence, fragmented aggregation","evidence":"Storage and cold chain capacity reported far below need; NISER cites under-funded mechanisation and extension","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"fx-scarcity-and-input-import-dependence-eth","title":"FX scarcity and input import dependence","scope":"ETH","segment":"inputs & seeds","root_causes":"Chronic forex shortages; state-controlled fertiliser procurement; delayed deliveries","evidence":"Public budget still finances ~78% of ag spending but inputs remain import-dependent (FAO MAFAP); recurrent fertiliser shortages reported","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"land-tenure-limits-investment-and-finance-eth","title":"Land tenure limits investment and finance","scope":"ETH","segment":"finance & insurance","root_causes":"Constitutional state ownership of land; small fragmented plots; use-rights only","evidence":"2024 Proclamation 1324 allows leasing and collateralising use-rights; only ~2.2bn birr in certificate-backed credit by Jan 2024","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"conflict-and-insecurity-in-core-producing-regions-eth","title":"Conflict and insecurity in core producing regions","scope":"ETH","segment":"logistics & market access","root_causes":"Armed conflict in Amhara and parts of Oromia; legacy of Tigray war","evidence":"Disruption of input distribution and market access in key surplus zones","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"weak-rural-digital-and-power-distribution-eth","title":"Weak rural digital and power distribution","scope":"ETH","segment":"digital connectivity","root_causes":"Late telecom liberalisation; low rural grid connections despite generation surplus","evidence":"Digital Agriculture Roadmap lists improving digital infrastructure and farmer digital literacy among its 32 priorities","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"landlocked-high-cost-logistics-eth","title":"Landlocked, high-cost logistics","scope":"ETH","segment":"transport","root_causes":"Single dominant port corridor (Djibouti); weak feeder roads; limited cold chain","evidence":"Separate Ministry of Logistics created in the 2026 cabinet reflects the bottleneck","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"chronic-under-funding-of-agriculture-ken","title":"Chronic under-funding of agriculture","scope":"KEN","segment":"finance & insurance","root_causes":"Treasury ceilings do not match sector priorities; heavy debt service crowds out development spending; functions split between national government and counties","evidence":"Ministry allocation of about Ksh75.49bn (~2.7% of budget); CS Kagwe told Parliament the sector is stuck near 3% against the 10% pledge (Citizen Digital, Feb 2026)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"low-irrigation-coverage-in-a-mostly-arid-country-ken","title":"Low irrigation coverage in a mostly arid country","scope":"KEN","segment":"irrigation & water","root_causes":"Rain-fed tradition; large-scheme failures (e.g. delays at Galana Kulalu); high capex and weak water-storage infrastructure","evidence":"664,000 irrigated acres in 2021/22 vs a 1.29m-acre target for 2027/28 under NISIP (Citizen Digital, Jun 2026)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"thin-ageing-public-extension-system-ken","title":"Thin, ageing public extension system","scope":"KEN","segment":"climate & extension","root_causes":"Devolved extension under-funded by counties; hiring freezes; about half of ministry staff near retirement","evidence":"CS Kagwe warning on staff retirements; Feb 2026 budget testimony cites weak extension services","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"input-costs-and-leakage-in-subsidy-delivery-ken","title":"Input costs and leakage in subsidy delivery","scope":"KEN","segment":"inputs & seeds","root_causes":"Currency volatility; reliance on imported fertiliser; past fake-fertiliser scandals; delays in subsidy releases","evidence":"Government rolled out 12.5m subsidised bags for the 2026 long rains via KIAMIS-registered farmers; high input costs cited by CS in Feb 2026","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"post-harvest-losses-and-weak-storage-for-grains-ken","title":"Post-harvest losses and weak storage for grains","scope":"KEN","segment":"storage & cold chain","root_causes":"Fragmented smallholder aggregation; hoarding and price speculation; under-used warehouse receipt system","evidence":"Jan 2026 30-day ultimatum to maize hoarders as government sought 4m bags for strategic reserves","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"low-irrigation-coverage-on-hilly-terrain-rwa","title":"Low irrigation coverage on hilly terrain","scope":"RWA","segment":"irrigation & water","root_causes":"Steep topography raises cost per hectare; marshland development is capital-intensive; dependence on donor financing","evidence":"~75,223 ha irrigated (15% of 493,050 ha irrigable); target 132,961 ha by 2029 (MINAGRI via New Times, Feb 2026)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"thin-commercial-finance-for-agriculture-rwa","title":"Thin commercial finance for agriculture","scope":"RWA","segment":"finance & insurance","root_causes":"Perceived risk, small ticket sizes, limited collateral value of tiny plots","evidence":"Agriculture ~6% of commercial lending; NST2 target ≥10% (MINAGRI, Jul 2026)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"land-scarcity-and-fragmentation-rwa","title":"Land scarcity and fragmentation","scope":"RWA","segment":"mechanization","root_causes":"High population density, inheritance-driven subdivision; slopes limit mechanisation","evidence":"PSTA5 names land scarcity, low productivity and post-harvest losses among core challenges","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"high-cost-landlocked-logistics-rwa","title":"High-cost, landlocked logistics","scope":"RWA","segment":"transport","root_causes":"Distance to Mombasa and Dar es Salaam ports; reliance on road freight; limited cold chain","evidence":"Government launched direct air-cargo for fresh produce to bypass ground constraints","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"fertiliser-price-exposure-rwa","title":"Fertiliser price exposure","scope":"RWA","segment":"inputs & seeds","root_causes":"Full import dependence for fertiliser; global price shocks","evidence":"2026/27 MINAGRI budget increase mainly for fertiliser subsidies, post-harvest storage and strategic reserves (KT Press, Jul 2026)","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"irrigated-area-far-below-potential-tza","title":"Irrigated area far below potential","scope":"TZA","segment":"irrigation & water","root_causes":"Historically low capital budgets, slow scheme construction, and dependence on rain-fed smallholdings.","evidence":"Agenda 10/30 targets 8.5 million ha irrigated. The borehole programme's first phase covers only ~13,500 acres, with 415 of 67,000 boreholes drilled (Aug 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"post-harvest-losses-and-weak-cold-chain-and-processing-tza","title":"Post-harvest losses and weak cold chain and processing","scope":"TZA","segment":"storage & cold chain","root_causes":"Few aggregation centres, poor rural roads and unreliable rural power.","evidence":"Agenda 10/30 aims to cut post-harvest losses from 35% to 5% and lift processing from 10% to 50%. The avocado plan needs 20 new collection centres.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"thin-extension-and-research-to-farm-delivery-tza","title":"Thin extension and research-to-farm delivery","scope":"TZA","segment":"climate & extension","root_causes":"Understaffed extension service and limited TARI funding. Fake-seed trade undermines adoption.","evidence":"NAESA is only beginning operations in July 2026. Crackdown on the fake-seed trade (Apr 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"limited-private-and-agri-finance-and-insurance-tza","title":"Limited private and agri finance and insurance","scope":"TZA","segment":"finance & insurance","root_causes":"High lending rates, land-tenure constraints on village land, and small TADB capitalization.","evidence":"Agenda 10/30 financing needs are estimated at TZS 33 trillion to 2030 (The Citizen). Agritech rounds are mostly pre-seed (MazaoHub $2m).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"low-mechanization-and-youth-engagement-tza","title":"Low mechanization and youth engagement","scope":"TZA","segment":"mechanization","root_causes":"Hand-hoe dominance, the high cost of equipment, and an ageing farmer base.","evidence":"The BBT youth programme (TZS 1.1tn budget anchor) and NIRC equipment handovers are still early-stage.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"animal-disease-control-and-biosecurity-zaf","title":"Animal disease control and biosecurity","scope":"ZAF","segment":"climate & extension","root_causes":"Eroded state veterinary capacity, vaccine-supply shortfalls (Onderstepoort Biological Products) and litigation over FMD management.","evidence":"Largest FMD outbreak on record. 13.5 million vaccines imported to end-June 2026, and exports to China are conditional on biosecurity (Food For Mzansi, Sept 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"port-rail-and-rural-road-bottlenecks-zaf","title":"Port, rail and rural-road bottlenecks","scope":"ZAF","segment":"transport","root_causes":"Transnet's operational decline, under-maintained provincial roads and slow private participation in freight rail and ports.","evidence":"The minister cites neglected rural roads, an inefficient harbour and rail problems, and is engaging the transport and public works ministries (Sept 2026).","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"limited-finance-and-support-for-emerging-black-farmers-zaf","title":"Limited finance and support for emerging/black farmers","scope":"ZAF","segment":"finance & insurance","root_causes":"Land Bank instability, provincial red tape and weak risk-sharing instruments.","evidence":"AAMP review (Jul 2026): limited access to blended finance for smallholders. Land Bank CEO resigned in Feb 2026 and an acting CEO was appointed.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"land-reform-and-tenure-uncertainty-zaf","title":"Land reform and tenure uncertainty","scope":"ZAF","segment":"finance & insurance","root_causes":"Slow redistribution and title transfer. Many beneficiaries lack title deeds, which limits their access to collateral.","evidence":"AAMP stakeholders cite uneven provincial alignment and red tape. Expropriation Act implementation is contested.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"energy-reliability-and-cost-for-irrigation-and-cold-chain-za","title":"Energy reliability and cost for irrigation and cold chain","scope":"ZAF","segment":"energy","root_causes":"Eskom's generation deficit and tariff hikes raise the cost of pumping and cold storage.","evidence":"Load-shedding years (2022-24) hit irrigation and cold chain, and agri-business sentiment remains sensitive to power and input costs.","evidence_source":null,"who_is_working":null,"opportunity":null,"needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"irrigation-deficit-rain-fed-farming-dominates-au","title":"Irrigation deficit: rain-fed farming dominates","scope":"AU","segment":"irrigation & water","root_causes":"High capital cost per irrigated ha, weak water governance and O&M of large public schemes, limited energy for pumping, little finance for small-scale/solar pumps, transboundary water politics.","evidence":"~6% of Africa's cropland is irrigated (~4% in SSA) vs ~37% in Asia; SSA withdraws only ~1% of its renewable water resources vs 219% in North Africa.","evidence_source":"IFPRI, 'Irrigating Africa' https://www.ifpri.org/blog/irrigating-africa","who_is_working":"AUDA-NEPAD/Africa Water Facility, World Bank (SIIP Sahel Irrigation Initiative), IWMI, FAO, AfDB TAAT; private: SunCulture, Futurepump, Oolu.","opportunity":"Pay-as-you-go solar pumps bundled with input credit and offtake; farmer-led irrigation finance facilities; irrigation-as-a-service; policymakers can de-risk via results-based subsidies and groundwater mapping.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"very-low-fertilizer-use-and-degrading-soils-au","title":"Very low fertilizer use and degrading soils","scope":"AU","segment":"inputs & seeds","root_causes":"Landed fertilizer prices 2-3x world prices due to port/inland logistics, small fragmented markets, FX shortages, weak soil testing and blanket recommendations, poorly targeted subsidy programs.","evidence":"Africa used 22.6 kg/ha in 2023 (16.3 in 2000) vs a global average of 116.4 kg/ha and Asia 186 kg/ha; the 2006 Abuja target of 50 kg/ha remains unmet. The AU Action Plan baseline is 18 kg/ha (2020) and the target is 54 kg/ha by 2034. Paradoxically, Africa produces ~30 Mt of fertilizer a year, about 2x what it consumes.","evidence_source":"FAO data via Africa Sustainability Matters (May 2026) https://africasustainabilitymatters.com/africa-still-far-below-fertilizer-targets-as-soil-degradation-threatens-food-security-and-agricultural-growth/ ; AU Africa Fertilizer & Soil Health Action Plan https://au.int/sites/default/files/documents/43208-doc-EN_Africa_Fertilizer_and_Soil_Health_Action_Plan.pdf","who_is_working":"AU/AUDA-NEPAD (Fertilizer & Soil Health Action Plan), AfDB Africa Fertilizer Financing Mechanism, AFAP, IFDC, OCP Africa, Dangote/Indorama, AGRA, One Acre Fund.","opportunity":"Blending hubs near demand, digital soil maps/soil testing with crop-specific blends, agro-dealer networks with embedded credit, regional trade so African producers (Morocco, Nigeria) supply African farmers.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"mechanization-hoe-based-smallholder-agriculture-au","title":"Mechanization: hoe-based smallholder agriculture","scope":"AU","segment":"mechanization","root_causes":"Small fragmented plots, no machinery finance or leasing, scarce spare parts and operators, import duties, collapse of 1970s state tractor schemes.","evidence":"Fewer than 2 tractors per 1,000 ha of cropland in Africa vs about 10 in South Asia and Latin America (FAO); ~70% of African farmers cultivate plots under 2 ha by hoe.","evidence_source":"Down To Earth citing FAO https://www.downtoearth.org.in/news/agriculture/what-needs-to-be-done-to-give-africa-s-smallholder-farmers-access-to-machinery-59201","who_is_working":"FAO/AU Sustainable Agricultural Mechanization Framework for Africa (SAMA), Hello Tractor, TROTRO Tractor, AGCO/John Deere dealer programs, AfDB TAAT, CIMMYT two-wheel tractor work.","opportunity":"Uber-for-tractors/custom hiring with IoT tracking and asset finance; two-wheel tractors and small machines suited to plots under 2 ha (the Bangladesh model); operator training academies.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"post-harvest-losses-au","title":"Post-harvest losses","scope":"AU","segment":"storage & cold chain","root_causes":"Poor on-farm storage, aflatoxin/pests, lack of drying equipment, bad roads delaying transport, no warehouse receipt systems, distress selling at harvest.","evidence":"SSA grain post-harvest losses are ~US$4bn/yr, ~15% of a ~US$27bn grain output (FAO/NRI 'Missing Food'); APHLIS cites Nigeria losing ~40% of food output, up to 70% for fruit and vegetables. The Kampala CAADP Declaration targets a 50% cut in post-harvest loss by 2035.","evidence_source":"FAO/World Bank/NRI via Farming Online https://farming.co.uk/news/grain-losses-in-sub-saharan-africa-could-total-%244-billion ; The Star (Kampala targets) https://www.the-star.co.ke/business/2025-01-15-africa-to-increase-agrifood-output-by-45-in-a-decade","who_is_working":"APHLIS, Rockefeller Foundation YieldWise, WFP, AGRA, PICS bags (Purdue), Eastern Africa Grain Council, warehouse receipt systems (Kenya, Ethiopia ECX, Ghana GCX).","opportunity":"Hermetic storage, mobile dryers and aggregation hubs; warehouse receipt finance; aflatoxin testing as a service.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"cold-chain-almost-absent-for-perishables-au","title":"Cold chain almost absent for perishables","scope":"AU","segment":"storage & cold chain","root_causes":"Unreliable and expensive grid power, high capex, fragmented informal markets, few reefer trucks, weak food safety enforcement.","evidence":"Cold storage is about 4.5 m3 per 1,000 people in Uganda (2023) and about 5 in Ethiopia vs ~38 in Kenya (GCCA 2020). India has 131 million m3 of refrigerated warehouse space. Nigeria reportedly meets less than 4% of its cold chain needs, a gap costing up to US$4.5bn/yr.","evidence_source":"Refindustry / IJR study https://refindustry.com/news/market-research/uganda-s-cold-storage-capacity-assessed-at-4-5-m-per-1-000-inhabitants ; Cooling Post (GCCA) https://www.coolingpost.com/world-news/coldstore-capacity-in-india-greater-than-usa/ ; African Marketing Confederation https://africanmarketingconfederation.org/poor-cold-chain-logistics-resulting-in-massive-food-wastage-in-africa/","who_is_working":"ColdHubs (Nigeria), Ecotutu, InspiraFarms, Koolboks, SokoFresh, Twiga-type aggregators, Africa Centre of Excellence for Sustainable Cooling (Rwanda), UNEP Cool Coalition.","opportunity":"Solar cold-rooms on pay-per-crate models, cooling-as-a-service, reefer logistics on export corridors, and pairing mini-grids with cold storage as an anchor load.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agri-finance-starvation-au","title":"Agri-finance starvation","scope":"AU","segment":"finance & insurance","root_causes":"Perceived high risk (weather, prices), no collateral because land is undocumented, high cost to serve dispersed farmers, sovereign yields crowding out private lending, lack of credit data.","evidence":"Under 3% of commercial bank lending in Africa goes to agriculture (Buhari at Dakar 2, Jan 2023), even though agriculture is ~16% of GDP and ~60% of employment. Kenya's agriculture CS made the same ~3% point in 2025.","evidence_source":"Nairametrics https://nairametrics.com/2023/01/26/less-than-3-of-commercial-lending-in-africa-goes-to-agriculture-president-buhari/ ; Business Daily Africa https://www.businessdailyafrica.com/bd/opinion-analysis/columnists/how-index-insurance-can-support-smallholder-farmers-4754250","who_is_working":"AfDB, AGRA, Mastercard Foundation, NIRSAL (Nigeria), Kenya AFC, IFAD, Apollo Agriculture, Pula, FarmDrive, Aceli Africa, Root Capital.","opportunity":"Credit scoring from satellite, mobile money and input-purchase data; embedded finance in input and offtake contracts; credit guarantees and first-loss funds; national farmer registries (the AgriStack model) to cut KYC costs.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"extension-systems-spread-too-thin-au","title":"Extension systems spread too thin","scope":"AU","segment":"climate & extension","root_causes":"Public hiring freezes since structural adjustment, low operating budgets (no fuel or transport), aging workforce, weak research-extension link, top-down messaging.","evidence":"Extension agent-to-farmer ratios in Africa commonly run 1:2,000 to 1:10,000 vs the FAO-recommended 1:500. The Fertilizer Action Plan aims for 70% of farmers to get effective agronomic advice by 2034.","evidence_source":"AGRA CESSA https://cessa.agra.org/farmer-awareness-and-participation/ ; AU Fertilizer Action Plan https://au.int/sites/default/files/documents/43208-doc-EN_Africa_Fertilizer_and_Soil_Health_Action_Plan.pdf","who_is_working":"Digital Green (Farmer.Chat), Ethiopia ATI 8028 hotline, One Acre Fund, Precision Development (PxD), CABI Plantwise, AFAAS, iShamba, Viamo/3-2-1.","opportunity":"Local-language AI advisory over voice/WhatsApp/IVR, paid village-based advisors and agro-dealer agents, and public extension refocused on content quality and verification.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"weak-formal-seed-systems-au","title":"Weak formal seed systems","scope":"AU","segment":"inputs & seeds","root_causes":"Informal farmer-saved seed dominates, slow variety release, small breeder pools, counterfeit seed, fragmented national regulations, little private investment in self-pollinated crops (legumes, sorghum).","evidence":"Kenya (SSPI/TASAI 2023): certified seed meets 53% of maize demand but only 4% of beans; KALRO has just 48 breeders across 4 crops. Only 7 of 21 COMESA states had domesticated harmonized seed regulations by 2018.","evidence_source":"The Star (SSPI 2023) https://www.the-star.co.ke/news/star-farmer/2025-08-20-seed-sector-thrives-on-maize-but-legumes-and-sorghum-lag-behind ; COMESA https://www.comesa.int/seven-comesa-states-have-harmonized-seed-regulations/","who_is_working":"TASAI, AGRA, CIMMYT, CGIAR Seed Equal, AATF, Seeds2B (Syngenta Foundation), AFSTA, regional seed bodies (COMESA, SADC SSSN, ECOWAS/CORAF).","opportunity":"Seed authentication (scratch codes, QR), early-generation seed companies for legumes, quality-declared seed schemes, and regional catalogue listings to sell across 20+ markets with one release.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"insecure-undocumented-land-tenure-au","title":"Insecure, undocumented land tenure","scope":"AU","segment":"finance & insurance","root_causes":"Dual customary/statutory systems, costly and slow registration, few surveyors, gender-biased inheritance, elite capture risk.","evidence":"Only ~10% of Africa's rural land is registered. Land transfers take twice as long and cost twice as much as in industrialized countries. Ghana, Kenya and Uganda each have under 10 surveyors per million people (Malaysia: 197). Scaling reforms would cost ~US$4.5bn over 10 years.","evidence_source":"World Bank (2013) https://www.worldbank.org/en/news/press-release/2013/07/22/how-africa-can-transform-land-tenure-revolutionize-agriculture-end-poverty","who_is_working":"World Bank land administration projects, AU Land Policy Centre, Rwanda's land tenure regularization, Ethiopia's second-level certification, Medici Land Governance, Cadasta, Landesa.","opportunity":"Low-cost drone/satellite plus community-validated mapping (fit-for-purpose land administration); digital certificates linked to farmer IDs so land rights can unlock credit.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"fragmented-intra-african-trade-and-an-agri-trade-deficit-au","title":"Fragmented intra-African trade and an agri trade deficit","scope":"AU","segment":"logistics & market access","root_causes":"Non-tariff barriers, SPS/standards differences, border delays, poor corridors, ad hoc export bans, payment/FX frictions, slow AfCFTA tariff gazetting.","evidence":"Intra-African trade was US$220.3bn in 2024, roughly 15% of Africa's trade (Afreximbank). Africa ran a US$16.7bn agricultural trade deficit in 2023 (imports ~US$110bn, exports ~US$93.3bn), and only 5 countries are net agri exporters (AATM 2025). AfCFTA: 50 ratifications, but only 26 states had gazetted tariff schedules by June 2026.","evidence_source":"Ecofin https://www.ecofinagency.com/finance/2706-47457-africa-s-trade-grows-13-9-in-2024-driven-by-afcfta-progress ; Ecofin/AATM https://www.ecofinagency.com/news-agriculture/2401-52237-africa-s-agri-trade-deficit-persists-as-only-five-countries-export-more-than-they-import ; tralac FAQ https://www.tralac.org/documents/resources/faqs/7994-afcfta-frequently-asked-questions-updated-september-2026.html","who_is_working":"AfCFTA Secretariat, Afreximbank (PAPSS, AfCFTA Adjustment Fund), TradeMark Africa, regional economic communities, AKADEMIYA2063 (AATM).","opportunity":"Cross-border B2B agri marketplaces, trade finance on PAPSS rails, SPS-compliant aggregation/testing, and regional brands that replace imported staples (rice, wheat, edible oil).","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"low-processing-and-value-addition-au","title":"Low processing and value addition","scope":"AU","segment":"processing","root_causes":"Expensive, unreliable power, tariff escalation in importing markets, weak industrial finance, small/inconsistent raw-material supply, skills gaps, and export taxes/levies that favor raw exports.","evidence":"West Africa grows over 70% of the world's cocoa but does only ~20% of global grinding, and ~75% of beans are exported raw. Only ~5% of Africa's cashew is processed before export; ~95% of raw nuts go to India/Vietnam. The Kampala target is to raise locally processed food to 35% of agrifood GDP by 2035.","evidence_source":"Kleos Advisory https://kleosadvisory.uk/why-is-so-little-value-added-in-africas-soft-commodity-value-chain/ ; The Star https://www.the-star.co.ke/business/2025-01-15-africa-to-increase-agrifood-output-by-45-in-a-decade","who_is_working":"AfDB Special Agro-Industrial Processing Zones (SAPZ), Afreximbank, Côte d'Ivoire/Ghana cocoa processing policies, African Cashew Alliance, Arise IIP (GDIZ Benin), UNIDO.","opportunity":"Mid-scale processing near farm clusters (cashew, cassava starch, soybean, tomato paste), tolling models, captive solar for agro-industrial parks, and export-processing incentives tied to AfCFTA rules of origin.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"rural-electricity-access-gap-au","title":"Rural electricity access gap","scope":"AU","segment":"energy","root_causes":"Utilities financially distressed, low rural load density, high grid extension cost, tariff and subsidy distortions, currency risk for off-grid investors.","evidence":"563 million people in SSA lacked electricity in 2024, 86% of the global deficit (up from 49% in 2010). Rural people without power rose from 376m to 447m (2010-2024). Mission 300 reported 64m people connected (WBG 59m + AfDB 5m) by Oct 2026 toward 300m by 2030.","evidence_source":"Tracking SDG7 2026 via Ecofin https://www.ecofinagency.com/news-industry/2506-56796-sub-saharan-africa-holds-86-of-global-electricity-access-gap-sdg-7-report ; GNA https://gna.org.gh/2026/10/world-bank-afdb-connect-64-million-africans-to-electricity/","who_is_working":"World Bank/AfDB Mission 300, SEforALL, Rockefeller/GEAPP, Power Africa (scaled back), mini-grid developers (Husk, CrossBoundary, Nuru), d.light, Sun King.","opportunity":"Productive-use appliances (milling, cooling, pumping) as mini-grid anchor loads; agri-PUE financing; solar-powered processing hubs.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"poor-rural-road-access-au","title":"Poor rural road access","scope":"AU","segment":"transport","root_causes":"Low maintenance budgets, reliance on unpaved earth roads cut off in rainy seasons, weak rural road agencies, focus on trunk corridors over feeder roads.","evidence":"Most African countries have a Rural Access Index (share of rural people within 2 km of an all-season road) of 20-40%, vs a 68% world country average. Nigeria alone has ~75 million rural people without access. Globally ~1.17bn rural people lack access.","evidence_source":"'Rural Access Index: A global study' (arXiv 2023) https://arxiv.org/pdf/2309.00505","who_is_working":"World Bank (SDG 9.1.1 custodian; rural roads projects), AfDB, SSATP, national roads funds, PIDA corridors, Bridges to Prosperity.","opportunity":"Performance-based feeder road maintenance contracts, trail bridges, geospatial road condition monitoring, and logistics platforms that aggregate loads to cut cost per km.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"digital-connectivity-usage-gap-more-than-coverage-gap-au","title":"Digital connectivity: usage gap more than coverage gap","scope":"AU","segment":"digital connectivity","root_causes":"Smartphone affordability, data prices, digital literacy, lack of local-language content, gender gap, rural power for charging.","evidence":"In SSA only 27% of the population (46% of adults) uses mobile internet. 60% live under coverage but don't use it (usage gap); 13% have no coverage (GSMA 2024).","evidence_source":"Connecting Africa (GSMA SOMIC 2024) https://www.connectingafrica.com/digital-divide/sub-saharan-africa-remains-the-least-connected-region-globally","who_is_working":"GSMA AgriTech, Safaricom DigiFarm, MTN, Airtel, Smart Africa, World Bank Digital Economy for Africa (DE4A), handset financing (M-KOPA).","opportunity":"Voice/USSD-first and offline-capable agri apps, smartphone financing bundled with farm credit, and village digital agents.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"agricultural-data-and-statistics-gap-au","title":"Agricultural data and statistics gap","scope":"AU","segment":"data","root_causes":"Underfunded national statistics offices, irregular agricultural censuses, no farmer registries, data siloed across ministries and donors, weak data-sharing rules.","evidence":"The 50x2030 Initiative exists to close the agricultural data gap in 50 low- and middle-income countries by 2030 (largely in Africa). The 4th CAADP Biennial Review (2023) found no country on track, set against a 9.29 benchmark, partly because of data gaps. By contrast India created 110 million digital farmer IDs by Oct 2026.","evidence_source":"Data4SDGs / 50x2030 https://www.data4sdgs.org/50by2030 ; ESAFF CAADP BR brief https://esaff.org/index-php/wp-content/uploads/2024/07/Policy-Brief-SADC-Performance-in-the-CAADP-BR-Report-wb.pdf ; Swarajya https://swarajyamag.com/news-brief/digital-agriculture-mission-crosses-11-crore-farmer-ids-five-months-before-march-2027-deadline","who_is_working":"FAO/World Bank/IFAD 50x2030, AKADEMIYA2063/ReSAKSS, Digital Earth Africa, Lacuna Fund, GODAN, national farmer registries (Kenya KIAMIS, Rwanda Smart Nkunganire, Ethiopia).","opportunity":"Interoperable farmer and land registries (open DPI), EO-based crop monitoring, and data cooperatives that let farmers monetize data under the AU Data Policy Framework.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"climate-risk-with-little-insurance-cover-au","title":"Climate risk with little insurance cover","scope":"AU","segment":"finance & insurance","root_causes":"Rain-fed dependence, basis risk in index insurance, low awareness, premiums unaffordable without subsidy, weak weather-station networks, little adaptation finance.","evidence":"Climate change has cut Africa's agricultural productivity growth by ~34% since 1961 (IPCC AR6/Ortiz-Bobea). Only ~6% of arable land is irrigated, so most farms are fully weather-exposed. Only ~3% of global climate finance reaches Africa. By comparison, the EU CAP supports risk-management tools for ~15% of EU farmers.","evidence_source":"UNCCD (IPCC) https://www.unccd.int/resources/unccd-library/agricultural-productivity-africa-declines-34 ; SCOR https://scor.com/en/expert-views/bridging-protection-gap-african-smallholder-farmers ; Business Daily https://www.businessdailyafrica.com/bd/opinion-analysis/columnists/how-index-insurance-can-support-smallholder-farmers-4754250","who_is_working":"African Risk Capacity (ARC), AfDB ADRiFi, Pula, ACRE Africa, Kenya KLIP, Global Shield, CGIAR climate programs, TAHMO weather stations.","opportunity":"Area-yield and satellite-index insurance bundled with credit and inputs, government-subsidized meso-level cover via cooperatives, and climate-smart seed plus advisory bundles.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"chronic-underinvestment-in-agricultural-r-d-au","title":"Chronic underinvestment in agricultural R&D","scope":"AU","segment":"climate & extension","root_causes":"Low government budgets, donor-dependent and volatile funding, aging scientists, small national systems that cannot reach scale.","evidence":"Only a handful of SSA countries reached the 1% of AgGDP research intensity target in 2016/17; ~60% of 49 countries with data were below 0.5%. SSA investment was 42% below attainable levels. Compare Brazil's Embrapa budget of R$3.4bn in 2017.","evidence_source":"ASTI/IFPRI 'ASTI at 20' https://www.asti.cgiar.org/sites/default/files/pdf/asti20/ASTIat20-Underinvestment.pdf ; Choices Magazine https://www.choicesmagazine.org/choices-magazine/theme-articles/the-agricultural-production-potential-of-latin-american-implications-for-global-food-supply-and-trade/brazils-agricultural-production-and-its-potential-as-global-food-supplier","who_is_working":"CGIAR, FARA, ASARECA/CORAF/CCARDESA, AATF, national research institutes (EIAR, KALRO, CSIR), Gates Foundation, AU genome-editing database.","opportunity":"Regional research consortia on shared crops; public-private breeding (gene editing under Kenya/Nigeria/Ghana guidelines); ag-research levies on exports (Brazil/Embrapa-style dedicated funding).","needs_review":false,"review_note":null,"last_verified":"2026-11-03"},{"id":"youth-bulge-without-agrifood-jobs-au","title":"Youth bulge without agrifood jobs","scope":"AU","segment":"processing","root_causes":"Low farm profitability, lack of land and finance for young people, perception of farming as poverty, skills mismatch, slow off-farm agrifood growth.","evidence":"10-12 million young Africans enter the workforce each year but only ~3 million formal jobs are created; the youth population will double to over 830 million by 2050 (AfDB Jobs for Youth strategy).","evidence_source":"tralac / AfDB Jobs for Youth in Africa 2016-2025 https://tralac.org/news/article/9843-afdb-group-strategy-for-jobs-for-youth-in-africa-2016-2025.html","who_is_working":"AfDB ENABLE Youth, Mastercard Foundation Young Africa Works, IITA Youth Agripreneurs, IFAD, AGRA, Kampala CAADP (women and youth commitment).","opportunity":"Youth service-provider models (spraying, mechanization, aggregation, digital agents), agrifood SME accelerators, and apprenticeship-linked processing parks.","needs_review":false,"review_note":null,"last_verified":"2026-11-03"}]$atlas$::jsonb)
on conflict (id) do update set title = excluded.title, scope = excluded.scope, segment = excluded.segment, root_causes = excluded.root_causes, evidence = excluded.evidence, evidence_source = excluded.evidence_source, who_is_working = excluded.who_is_working, opportunity = excluded.opportunity, needs_review = excluded.needs_review, review_note = excluded.review_note, last_verified = excluded.last_verified;

commit;
